#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      tmp[i][j] = SCALAR_VAL(0.0);
    }
    for (k = 0; k < _PB_NK; k++) {
      double a_val = alpha * A[i][k];
      j = 0;
      size_t vlmax = __riscv_vsetvlmax_e64m8();
      vfloat64m8_t va = __riscv_vfmv_v_f_f64m8(a_val, vlmax);
      for (; j + vlmax <= _PB_NJ; j += vlmax) {
        vfloat64m8_t vb = __riscv_vle64_v_f64m8(&B[k][j], vlmax);
        vfloat64m8_t vt = __riscv_vle64_v_f64m8(&tmp[i][j], vlmax);
        vt = __riscv_vfmacc_vv_f64m8(vt, va, vb, vlmax);
        __riscv_vse64_v_f64m8(&tmp[i][j], vt, vlmax);
      }
      for (; j < _PB_NJ; j++) {
        tmp[i][j] += a_val * B[k][j];
      }
    }
  }
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; j++) {
      D[i][j] *= beta;
    }
    for (k = 0; k < _PB_NJ; k++) {
      double t_val = tmp[i][k];
      j = 0;
      size_t vlmax = __riscv_vsetvlmax_e64m8();
      vfloat64m8_t vt = __riscv_vfmv_v_f_f64m8(t_val, vlmax);
      for (; j + vlmax <= _PB_NL; j += vlmax) {
        vfloat64m8_t vc = __riscv_vle64_v_f64m8(&C[k][j], vlmax);
        vfloat64m8_t vd = __riscv_vle64_v_f64m8(&D[i][j], vlmax);
        vd = __riscv_vfmacc_vv_f64m8(vd, vt, vc, vlmax);
        __riscv_vse64_v_f64m8(&D[i][j], vd, vlmax);
      }
      for (; j < _PB_NL; j++) {
        D[i][j] += t_val * C[k][j];
      }
    }
  }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      tmp[i][j] = SCALAR_VAL(0.0);
    }
    for (k = 0; k < _PB_NK; k++) {
      float a_val = alpha * A[i][k];
      j = 0;
      size_t vlmax = __riscv_vsetvlmax_e32m8();
      vfloat32m8_t va = __riscv_vfmv_v_f_f32m8(a_val, vlmax);
      for (; j + vlmax <= _PB_NJ; j += vlmax) {
        vfloat32m8_t vb = __riscv_vle32_v_f32m8(&B[k][j], vlmax);
        vfloat32m8_t vt = __riscv_vle32_v_f32m8(&tmp[i][j], vlmax);
        vt = __riscv_vfmacc_vv_f32m8(vt, va, vb, vlmax);
        __riscv_vse32_v_f32m8(&tmp[i][j], vt, vlmax);
      }
      for (; j < _PB_NJ; j++) {
        tmp[i][j] += a_val * B[k][j];
      }
    }
  }
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; j++) {
      D[i][j] *= beta;
    }
    for (k = 0; k < _PB_NJ; k++) {
      float t_val = tmp[i][k];
      j = 0;
      size_t vlmax = __riscv_vsetvlmax_e32m8();
      vfloat32m8_t vt = __riscv_vfmv_v_f_f32m8(t_val, vlmax);
      for (; j + vlmax <= _PB_NL; j += vlmax) {
        vfloat32m8_t vc = __riscv_vle32_v_f32m8(&C[k][j], vlmax);
        vfloat32m8_t vd = __riscv_vle32_v_f32m8(&D[i][j], vlmax);
        vd = __riscv_vfmacc_vv_f32m8(vd, vt, vc, vlmax);
        __riscv_vse32_v_f32m8(&D[i][j], vd, vlmax);
      }
      for (; j < _PB_NL; j++) {
        D[i][j] += t_val * C[k][j];
      }
    }
  }
#else
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	tmp[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  tmp[i][j] += alpha * A[i][k] * B[k][j];
      }
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	D[i][j] *= beta;
	for (k = 0; k < _PB_NJ; ++k)
	  D[i][j] += tmp[i][k] * C[k][j];
      }
#endif

#pragma endscop

}

