static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

  /* E = A * B */
  for (i = 0; i < _PB_NI; i++)
    {
      for (j = 0; j < _PB_NJ; j++)
        E[i][j] = SCALAR_VAL(0.0);

      for (k = 0; k < _PB_NK; ++k)
        {
          DATA_TYPE a_ik = A[i][k];
          j = 0;
          #if defined(__riscv_vector)
          size_t vlmax = __riscv_vsetvlmax_e64m1();
          vfloat64m1_t va = __riscv_vfmv_v_f_f64m1(a_ik, vlmax);
          for (; j + vlmax <= _PB_NJ; j += vlmax)
            {
              vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[k][j], vlmax);
              vfloat64m1_t ve = __riscv_vle64_v_f64m1(&E[i][j], vlmax);
              ve = __riscv_vfmacc_vv_f64m1(ve, va, vb, vlmax);
              __riscv_vse64_v_f64m1(&E[i][j], ve, vlmax);
            }
          #endif
          for (; j < _PB_NJ; j++)
            E[i][j] += a_ik * B[k][j];
        }
    }

  /* F = C * D */
  for (i = 0; i < _PB_NJ; i++)
    {
      for (j = 0; j < _PB_NL; j++)
        F[i][j] = SCALAR_VAL(0.0);

      for (k = 0; k < _PB_NM; ++k)
        {
          DATA_TYPE c_ik = C[i][k];
          j = 0;
          #if defined(__riscv_vector)
          size_t vlmax = __riscv_vsetvlmax_e64m1();
          vfloat64m1_t vc = __riscv_vfmv_v_f_f64m1(c_ik, vlmax);
          for (; j + vlmax <= _PB_NL; j += vlmax)
            {
              vfloat64m1_t vd = __riscv_vle64_v_f64m1(&D[k][j], vlmax);
              vfloat64m1_t vf = __riscv_vle64_v_f64m1(&F[i][j], vlmax);
              vf = __riscv_vfmacc_vv_f64m1(vf, vc, vd, vlmax);
              __riscv_vse64_v_f64m1(&F[i][j], vf, vlmax);
            }
          #endif
          for (; j < _PB_NL; j++)
            F[i][j] += c_ik * D[k][j];
        }
    }

  /* G = E * F */
  for (i = 0; i < _PB_NI; i++)
    {
      for (j = 0; j < _PB_NL; j++)
        G[i][j] = SCALAR_VAL(0.0);

      for (k = 0; k < _PB_NJ; ++k)
        {
          DATA_TYPE e_ik = E[i][k];
          j = 0;
          #if defined(__riscv_vector)
          size_t vlmax = __riscv_vsetvlmax_e64m1();
          vfloat64m1_t ve = __riscv_vfmv_v_f_f64m1(e_ik, vlmax);
          for (; j + vlmax <= _PB_NL; j += vlmax)
            {
              vfloat64m1_t vff = __riscv_vle64_v_f64m1(&F[k][j], vlmax);
              vfloat64m1_t vg = __riscv_vle64_v_f64m1(&G[i][j], vlmax);
              vg = __riscv_vfmacc_vv_f64m1(vg, ve, vff, vlmax);
              __riscv_vse64_v_f64m1(&G[i][j], vg, vlmax);
            }
          #endif
          for (; j < _PB_NL; j++)
            G[i][j] += e_ik * F[k][j];
        }
    }
#pragma endscop

}

