static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0)+mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0)+mul2;
  f = d;

 for (t=1; t<=_PB_TSTEPS; t++) {

    for (i=1; i<_PB_N-1; i++) {
      v[0][i] = SCALAR_VAL(1.0);
      p[i][0] = SCALAR_VAL(0.0);
      q[i][0] = v[0][i];
      for (j=1; j<_PB_N-1; j++) {
        p[i][j] = -c / (a*p[i][j-1]+b);
        q[i][j] = (-d*u[j][i-1]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*d)*u[j][i] - f*u[j][i+1]-a*q[i][j-1])/(a*p[i][j-1]+b);
      }

      v[_PB_N-1][i] = SCALAR_VAL(1.0);
      for (j=_PB_N-2; j>=1; j--) {
        v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
      }
    }

    for (i=1; i<_PB_N-1; i++) {
      u[i][0] = SCALAR_VAL(1.0);
      p[i][0] = SCALAR_VAL(0.0);
      q[i][0] = u[i][0];
      for (j=1; j<_PB_N-1; j++) {
        p[i][j] = -f / (d*p[i][j-1]+e);
        q[i][j] = (-a*v[i-1][j]+(SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*a)*v[i][j] - c*v[i+1][j]-d*q[i][j-1])/(d*p[i][j-1]+e);
      }
      u[i][_PB_N-1] = SCALAR_VAL(1.0);
      for (j=_PB_N-2; j>=1; j--) {
        u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
      }
    }
  }
#pragma endscop
}

static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

#if defined(__riscv_vector)
  for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      j = 0;
      size_t vl = __riscv_vsetvlmax_e64m2();
      vfloat64m2_t vsum = __riscv_vfmv_v_f_f64m2(0.0, vl);
      for (; j + vl <= _PB_N; j += vl)
	{
	  vfloat64m2_t va = __riscv_vle64_v_f64m2(&A[i][j], vl);
	  vfloat64m2_t vx = __riscv_vle64_v_f64m2(&x[j], vl);
	  vsum = __riscv_vfmacc_vv_f64m2(vsum, va, vx, vl);
	}
      vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
      vfloat64m1_t vred = __riscv_vfredusum_vs_f64m2_f64m1(vsum, vzero, vl);
      sum = __riscv_vfmv_f_s_f64m1_f64(vred);
      for (; j < _PB_N; j++)
	sum = sum + A[i][j] * x[j];
      tmp[i] = sum;

      DATA_TYPE t = tmp[i];
      j = 0;
      vl = __riscv_vsetvlmax_e64m2();
      for (; j + vl <= _PB_N; j += vl)
	{
	  vfloat64m2_t va = __riscv_vle64_v_f64m2(&A[i][j], vl);
	  vfloat64m2_t vy = __riscv_vle64_v_f64m2(&y[j], vl);
	  vy = __riscv_vfmacc_vf_f64m2(vy, t, va, vl);
	  __riscv_vse64_v_f64m2(&y[j], vy, vl);
	}
      for (; j < _PB_N; j++)
	y[j] = y[j] + A[i][j] * t;
    }
#else
  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	tmp[i] = tmp[i] + A[i][j] * x[j];
      for (j = 0; j < _PB_N; j++)
	y[j] = y[j] + A[i][j] * tmp[i];
    }
#endif
#pragma endscop

}

