static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#if defined(__riscv_vector)
  // Initialize s to zero using vectors
  for (j = 0; j < m; ) {
    size_t vl = __riscv_vsetvl_e64m8(m - j);
    vfloat64m8_t zero = __riscv_vfmv_v_f_f64m8(0.0, vl);
    __riscv_vse64_v_f64m8(&s[j], zero, vl);
    j += vl;
  }

  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      DATA_TYPE ri = r[i];
      DATA_TYPE qi = 0.0;

      // Process M dimension with vectorization
      // Use e64m4 to have two vector registers available for dual accumulation
      for (j = 0; j < _PB_M; ) {
        size_t vl = __riscv_vsetvl_e64m4(_PB_M - j);

        // Load A[i][j:j+vl]
        vfloat64m4_t a_vec = __riscv_vle64_v_f64m4(&A[i][j], vl);

        // Load s[j:j+vl]
        vfloat64m4_t s_vec = __riscv_vle64_v_f64m4(&s[j], vl);

        // Load p[j:j+vl]
        vfloat64m4_t p_vec = __riscv_vle64_v_f64m4(&p[j], vl);

        // s[j] = s[j] + r[i] * A[i][j]
        vfloat64m4_t s_update = __riscv_vfmacc_vf_f64m4(s_vec, ri, a_vec, vl);
        __riscv_vse64_v_f64m4(&s[j], s_update, vl);

        // q[i] = q[i] + A[i][j] * p[j] (partial sum)
        vfloat64m4_t q_partial = __riscv_vfmul_vv_f64m4(a_vec, p_vec, vl);
        vfloat64m1_t q_sum = __riscv_vfredusum_vs_f64m4_f64m1(q_partial, __riscv_vfmv_s_f_f64m1(0.0, 1), vl);
        qi += __riscv_vfmv_f_s_f64m1_f64(q_sum);

        j += vl;
      }

      q[i] = qi;
    }
#else
#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;
  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r[i] * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
#pragma endscop
#endif
}

