static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

     for (j = 0; j < i; j++) {
        DATA_TYPE sum = A[i][j];
#if defined(__riscv_vector)
        size_t vlmax = __riscv_vsetvlmax_e64m1();
        vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
        int k_vec;
        for (k_vec = 0; k_vec + vlmax <= j; k_vec += vlmax) {
           vfloat64m1_t vi = __riscv_vle64_v_f64m1(&A[i][k_vec], vlmax);
           vfloat64m1_t vj = __riscv_vle64_v_f64m1(&A[j][k_vec], vlmax);
           vsum = __riscv_vfmacc_vv_f64m1(vsum, vi, vj, vlmax);
        }
        sum -= __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m1_f64m1(vsum, __riscv_vfmv_s_f_f64m1(0.0, vlmax), vlmax));
        for (k = k_vec; k < j; k++) {
           sum -= A[i][k] * A[j][k];
        }
#else
        for (k = 0; k < j; k++) {
           sum -= A[i][k] * A[j][k];
        }
#endif
        A[i][j] = sum / A[j][j];
     }

     DATA_TYPE sum = A[i][i];
#if defined(__riscv_vector)
     size_t vlmax = __riscv_vsetvlmax_e64m1();
     vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
     int k_vec;
     for (k_vec = 0; k_vec + vlmax <= i; k_vec += vlmax) {
        vfloat64m1_t vi = __riscv_vle64_v_f64m1(&A[i][k_vec], vlmax);
        vsum = __riscv_vfmacc_vv_f64m1(vsum, vi, vi, vlmax);
     }
     sum -= __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m1_f64m1(vsum, __riscv_vfmv_s_f_f64m1(0.0, vlmax), vlmax));
     for (k = k_vec; k < i; k++) {
        sum -= A[i][k] * A[i][k];
     }
#else
     for (k = 0; k < i; k++) {
        sum -= A[i][k] * A[i][k];
     }
#endif
     A[i][i] = SQRT_FUN(sum);
  }
#pragma endscop

}

