static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);

#if defined(__riscv_vector)
  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

  /* Compute mean[j] = sum(data[i][j]) / float_n */
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; )
	{
	  size_t vl = __riscv_vsetvl_e64m8(_PB_N - i);
	  vfloat64m8_t vdata;
	  if (sizeof(DATA_TYPE) == 8)
	    vdata = __riscv_vle64_v_f64m8((double *)&data[i][j], vl);
	  else
	    {
	      /* DATA_TYPE is float (32-bit) */
	      vfloat32m4_t vdata32 = __riscv_vle32_v_f32m4((float *)&data[i][j], vl);
	      vdata = __riscv_vfwcvt_f_f_v_f64m8(vdata32, vl);
	    }
	  vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);
	  vsum = __riscv_vfredusum_vs_f64m8_f64m1(vdata, vsum, vl);
	  sum += __riscv_vfmv_f_s_f64m1_f64(vsum);
	  i += vl;
	}
      mean[j] = sum / float_n;
    }

  /* Compute stddev */
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; )
	{
	  size_t vl = __riscv_vsetvl_e64m8(_PB_N - i);
	  vfloat64m8_t vdata;
	  if (sizeof(DATA_TYPE) == 8)
	    vdata = __riscv_vle64_v_f64m8((double *)&data[i][j], vl);
	  else
	    {
	      vfloat32m4_t vdata32 = __riscv_vle32_v_f32m4((float *)&data[i][j], vl);
	      vdata = __riscv_vfwcvt_f_f_v_f64m8(vdata32, vl);
	    }
	  vfloat64m8_t vmean = __riscv_vfmv_v_f_f64m8(mean[j], vl);
	  vfloat64m8_t vdiff = __riscv_vfsub_vv_f64m8(vdata, vmean, vl);
	  vfloat64m8_t vsq = __riscv_vfmul_vv_f64m8(vdiff, vdiff, vl);
	  vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);
	  vsum = __riscv_vfredusum_vs_f64m8_f64m1(vsq, vsum, vl);
	  sum += __riscv_vfmv_f_s_f64m1_f64(vsum);
	  i += vl;
	}
      stddev[j] = sum / float_n;
      stddev[j] = SQRT_FUN(stddev[j]);
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }

  /* Normalize data */
  for (i = 0; i < _PB_N; i++)
    {
      for (j = 0; j < _PB_M; )
	{
	  size_t vl = __riscv_vsetvl_e64m8(_PB_M - j);
	  vfloat64m8_t vmean, vstddev, vdata;
	  if (sizeof(DATA_TYPE) == 8)
	    {
	      vmean = __riscv_vle64_v_f64m8((double *)&mean[j], vl);
	      vstddev = __riscv_vle64_v_f64m8((double *)&stddev[j], vl);
	      vdata = __riscv_vle64_v_f64m8((double *)&data[i][j], vl);
	    }
	  else
	    {
	      vfloat32m4_t vmean32 = __riscv_vle32_v_f32m4((float *)&mean[j], vl);
	      vfloat32m4_t vstddev32 = __riscv_vle32_v_f32m4((float *)&stddev[j], vl);
	      vfloat32m4_t vdata32 = __riscv_vle32_v_f32m4((float *)&data[i][j], vl);
	      vmean = __riscv_vfwcvt_f_f_v_f64m8(vmean32, vl);
	      vstddev = __riscv_vfwcvt_f_f_v_f64m8(vstddev32, vl);
	      vdata = __riscv_vfwcvt_f_f_v_f64m8(vdata32, vl);
	    }
	  vfloat64m8_t vdiff = __riscv_vfsub_vv_f64m8(vdata, vmean, vl);
	  vfloat64m8_t vscale = __riscv_vfmul_vf_f64m8(vstddev, sqrt_float_n, vl);
	  vfloat64m8_t vres = __riscv_vfdiv_vv_f64m8(vdiff, vscale, vl);
	  if (sizeof(DATA_TYPE) == 8)
	    __riscv_vse64_v_f64m8((double *)&data[i][j], vres, vl);
	  else
	    {
	      vfloat32m4_t vres32 = __riscv_vfncvt_f_f_w_f32m4(vres, vl);
	      __riscv_vse32_v_f32m4((float *)&data[i][j], vres32, vl);
	    }
	  j += vl;
	}
    }

  /* Compute correlation matrix */
  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
	{
	  DATA_TYPE sum = SCALAR_VAL(0.0);
	  for (k = 0; k < _PB_N; )
	    {
	      size_t vl = __riscv_vsetvl_e64m8(_PB_N - k);
	      vfloat64m8_t vki, vkj;
	      if (sizeof(DATA_TYPE) == 8)
		{
		  vki = __riscv_vle64_v_f64m8((double *)&data[k][i], vl);
		  vkj = __riscv_vle64_v_f64m8((double *)&data[k][j], vl);
		}
	      else
		{
		  vfloat32m4_t vki32 = __riscv_vle32_v_f32m4((float *)&data[k][i], vl);
		  vfloat32m4_t vkj32 = __riscv_vle32_v_f32m4((float *)&data[k][j], vl);
		  vki = __riscv_vfwcvt_f_f_v_f64m8(vki32, vl);
		  vkj = __riscv_vfwcvt_f_f_v_f64m8(vkj32, vl);
		}
	      vfloat64m8_t vmul = __riscv_vfmul_vv_f64m8(vki, vkj, vl);
	      vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);
	      vsum = __riscv_vfredusum_vs_f64m8_f64m1(vmul, vsum, vl);
	      sum += __riscv_vfmv_f_s_f64m1_f64(vsum);
	      k += vl;
	    }
	  corr[i][j] = sum;
	  corr[j][i] = sum;
	}
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);

#else
  /* Original scalar code for non-RISC-V targets */
#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
	mean[j] += data[i][j];
      mean[j] /= float_n;
    }

   for (j = 0; j < _PB_M; j++)
    {
      stddev[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        stddev[j] += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
      stddev[j] /= float_n;
      stddev[j] = SQRT_FUN(stddev[j]);


      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }


  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= SQRT_FUN(float_n) * stddev[j];
      }


  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          corr[i][j] = SCALAR_VAL(0.0);
          for (k = 0; k < _PB_N; k++)
            corr[i][j] += (data[k][i] * data[k][j]);
          corr[j][i] = corr[i][j];
        }
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop
#endif
}

