static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#if defined(__riscv_vector)
  /* Compute mean using RVV */
  for (j = 0; j < m; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int vlmax = __riscv_vsetvlmax_e64m1();
      vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, vlmax);

      for (i = 0; i < n; ) {
        int vl = __riscv_vsetvl_e64m1(n - i);
        vfloat64m1_t vdata = __riscv_vle64_v_f64m1(&data[i][j], vl);
        vsum = __riscv_vfredusum_vs_f64m1_f64m1(vdata, vsum, vl);
        i += vl;
      }

      sum = __riscv_vfmv_f_s_f64m1_f64(vsum);
      mean[j] = sum / float_n;
    }

  /* Center data using RVV */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j < m; ) {
        int vl = __riscv_vsetvl_e64m1(m - j);
        vfloat64m1_t vmean = __riscv_vle64_v_f64m1(&mean[j], vl);
        vfloat64m1_t vdata = __riscv_vle64_v_f64m1(&data[i][j], vl);
        vdata = __riscv_vfsub_vv_f64m1(vdata, vmean, vl);
        __riscv_vse64_v_f64m1(&data[i][j], vdata, vl);
        j += vl;
      }
    }

  /* Compute covariance using RVV */
  for (i = 0; i < m; i++)
    {
      for (j = i; j < m; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);
          int vlmax = __riscv_vsetvlmax_e64m1();
          vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, vlmax);

          for (k = 0; k < n; ) {
            int vl = __riscv_vsetvl_e64m1(n - k);
            vfloat64m1_t vdata_i = __riscv_vle64_v_f64m1(&data[k][i], vl);
            vfloat64m1_t vdata_j = __riscv_vle64_v_f64m1(&data[k][j], vl);
            vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(vdata_i, vdata_j, vl);
            vsum = __riscv_vfredusum_vs_f64m1_f64m1(vprod, vsum, vl);
            k += vl;
          }

          sum = __riscv_vfmv_f_s_f64m1_f64(vsum);
          cov[i][j] = sum / (float_n - SCALAR_VAL(1.0));
          cov[j][i] = cov[i][j];
        }
    }
#else
#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        cov[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
	  cov[i][j] += data[k][i] * data[k][j];
        cov[i][j] /= (float_n - SCALAR_VAL(1.0));
        cov[j][i] = cov[i][j];
      }
#pragma endscop
#endif
}

