static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
   {
     size_t vlmax = __riscv_vsetvlmax_e64m8();
     vfloat64m8_t vsum = __riscv_vfmv_v_f_f64m8(0.0, vlmax);
     size_t vl;
     for (i = 0; i < k; i += vl) {
       vl = __riscv_vsetvl_e64m8(k - i);
       vfloat64m8_t vy = __riscv_vle64_v_f64m8(&y[i], vl);
       vfloat64m8_t vr = __riscv_vlse64_v_f64m8(&r[k-i-1], -sizeof(DATA_TYPE), vl);
       vsum = __riscv_vfmacc_vv_f64m8(vsum, vr, vy, vl);
     }
     vfloat64m1_t vred = __riscv_vfredusum_vs_f64m8_f64m1(vsum, __riscv_vfmv_v_f_f64m1(0.0, 1), vlmax);
     sum = __riscv_vfmv_f_s_f64m1_f64(vred);
   }
#else
   for (i=0; i<k; i++) {
      sum += r[k-i-1]*y[i];
   }
#endif

   alpha = - (r[k] + sum)/beta;

#if defined(__riscv_vector)
   {
     size_t vl;
     // Process forward and reverse elements with higher LMUL for better throughput
     for (i = 0; i < k; i += vl) {
       vl = __riscv_vsetvl_e64m8(k - i);
       vfloat64m8_t vy = __riscv_vle64_v_f64m8(&y[i], vl);
       vfloat64m8_t vyk = __riscv_vlse64_v_f64m8(&y[k-i-1], -sizeof(DATA_TYPE), vl);
       vfloat64m8_t vz = __riscv_vfmacc_vf_f64m8(vy, alpha, vyk, vl);
       __riscv_vse64_v_f64m8(&y[i], vz, vl);
     }
   }
#else
   for (i=0; i<k; i++) {
      z[i] = y[i] + alpha*y[k-i-1];
   }
   for (i=0; i<k; i++) {
     y[i] = z[i];
   }
#endif
   y[k] = alpha;
 }
#pragma endscop

}

