static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];
      for (i = 1; i < _PB_NX; i++)
	{
	  DATA_TYPE *ey_row = ey[i];
	  DATA_TYPE *hz_row = hz[i];
	  DATA_TYPE *hz_prev = hz[i-1];
	  j = 0;
#if defined(__riscv_vector)
	  size_t vlmax = __riscv_vsetvlmax_e64m8();
	  for (; j + vlmax <= _PB_NY; j += vlmax)
	    {
	      vfloat64m8_t vey = __riscv_vle64_v_f64m8(&ey_row[j], vlmax);
	      vfloat64m8_t vhz = __riscv_vle64_v_f64m8(&hz_row[j], vlmax);
	      vfloat64m8_t vhzp = __riscv_vle64_v_f64m8(&hz_prev[j], vlmax);
	      vfloat64m8_t vdiff = __riscv_vfsub_vv_f64m8(vhz, vhzp, vlmax);
	      vfloat64m8_t vscaled = __riscv_vfmul_vf_f64m8(vdiff, 0.5, vlmax);
	      vey = __riscv_vfsub_vv_f64m8(vey, vscaled, vlmax);
	      __riscv_vse64_v_f64m8(&ey_row[j], vey, vlmax);
	    }
#endif
	  for (; j < _PB_NY; j++)
	    ey_row[j] = ey_row[j] - SCALAR_VAL(0.5)*(hz_row[j]-hz_prev[j]);
	}
      for (i = 0; i < _PB_NX; i++)
	{
	  DATA_TYPE *ex_row = ex[i];
	  DATA_TYPE *hz_row = hz[i];
	  j = 1;
#if defined(__riscv_vector)
	  size_t vlmax = __riscv_vsetvlmax_e64m8();
	  for (; j + vlmax <= _PB_NY; j += vlmax)
	    {
	      vfloat64m8_t vex = __riscv_vle64_v_f64m8(&ex_row[j], vlmax);
	      vfloat64m8_t vhz = __riscv_vle64_v_f64m8(&hz_row[j], vlmax);
	      vfloat64m8_t vhzm = __riscv_vle64_v_f64m8(&hz_row[j-1], vlmax);
	      vfloat64m8_t vdiff = __riscv_vfsub_vv_f64m8(vhz, vhzm, vlmax);
	      vfloat64m8_t vscaled = __riscv_vfmul_vf_f64m8(vdiff, 0.5, vlmax);
	      vex = __riscv_vfsub_vv_f64m8(vex, vscaled, vlmax);
	      __riscv_vse64_v_f64m8(&ex_row[j], vex, vlmax);
	    }
#endif
	  for (; j < _PB_NY; j++)
	    ex_row[j] = ex_row[j] - SCALAR_VAL(0.5)*(hz_row[j]-hz_row[j-1]);
	}
      for (i = 0; i < _PB_NX - 1; i++)
	{
	  DATA_TYPE *hz_row = hz[i];
	  DATA_TYPE *ex_row = ex[i];
	  DATA_TYPE *ey_row = ey[i];
	  DATA_TYPE *ey_next = ey[i+1];
	  j = 0;
#if defined(__riscv_vector)
	  size_t vlmax = __riscv_vsetvlmax_e64m8();
	  for (; j + vlmax <= _PB_NY - 1; j += vlmax)
	    {
	      vfloat64m8_t vhz = __riscv_vle64_v_f64m8(&hz_row[j], vlmax);
	      vfloat64m8_t vex = __riscv_vle64_v_f64m8(&ex_row[j], vlmax);
	      vfloat64m8_t vexp = __riscv_vle64_v_f64m8(&ex_row[j+1], vlmax);
	      vfloat64m8_t vey = __riscv_vle64_v_f64m8(&ey_row[j], vlmax);
	      vfloat64m8_t veyn = __riscv_vle64_v_f64m8(&ey_next[j], vlmax);
	      vfloat64m8_t vdx = __riscv_vfsub_vv_f64m8(vexp, vex, vlmax);
	      vfloat64m8_t vdy = __riscv_vfsub_vv_f64m8(veyn, vey, vlmax);
	      vfloat64m8_t vsum = __riscv_vfadd_vv_f64m8(vdx, vdy, vlmax);
	      vfloat64m8_t vscaled = __riscv_vfmul_vf_f64m8(vsum, 0.7, vlmax);
	      vhz = __riscv_vfsub_vv_f64m8(vhz, vscaled, vlmax);
	      __riscv_vse64_v_f64m8(&hz_row[j], vhz, vlmax);
	    }
#endif
	  for (; j < _PB_NY - 1; j++)
	    hz_row[j] = hz_row[j] - SCALAR_VAL(0.7)*  (ex_row[j+1] - ex_row[j] +
				       ey_next[j] - ey_row[j]);
	}
    }

#pragma endscop
}

