#include <riscv_vector.h>
#endif

static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#if defined(__riscv_vector) && defined(__riscv_float_abi_soft)
  /* RVV not usable without hardware FP */
#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	for (j = 0; j < _PB_N; j++)
	  path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	    path[i][j] : path[i][k] + path[k][j];
    }
#pragma endscop
#elif defined(__riscv_vector)
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	{
	  DATA_TYPE path_ik = path[i][k];
	  DATA_TYPE *path_i = path[i];
	  DATA_TYPE *path_k = path[k];
	  j = 0;
#if defined(DATA_TYPE_IS_DOUBLE)
	  size_t vlmax = __riscv_vsetvlmax_e64m1();
	  vfloat64m1_t v_ik = __riscv_vfmv_v_f_f64m1(path_ik, vlmax);
	  for (; j + vlmax <= _PB_N; j += vlmax)
	    {
	      vfloat64m1_t v_ij = __riscv_vle64_v_f64m1(&path_i[j], vlmax);
	      vfloat64m1_t v_kj = __riscv_vle64_v_f64m1(&path_k[j], vlmax);
	      vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_ik, v_kj, vlmax);
	      vfloat64m1_t v_min = __riscv_vfmin_vv_f64m1(v_ij, v_sum, vlmax);
	      __riscv_vse64_v_f64m1(&path_i[j], v_min, vlmax);
	    }
#elif defined(DATA_TYPE_IS_FLOAT)
	  size_t vlmax = __riscv_vsetvlmax_e32m1();
	  vfloat32m1_t v_ik = __riscv_vfmv_v_f_f32m1(path_ik, vlmax);
	  for (; j + vlmax <= _PB_N; j += vlmax)
	    {
	      vfloat32m1_t v_ij = __riscv_vle32_v_f32m1(&path_i[j], vlmax);
	      vfloat32m1_t v_kj = __riscv_vle32_v_f32m1(&path_k[j], vlmax);
	      vfloat32m1_t v_sum = __riscv_vfadd_vv_f32m1(v_ik, v_kj, vlmax);
	      vfloat32m1_t v_min = __riscv_vfmin_vv_f32m1(v_ij, v_sum, vlmax);
	      __riscv_vse32_v_f32m1(&path_i[j], v_min, vlmax);
	    }
#else
	  /* Unknown DATA_TYPE, fallback to scalar */
#endif
	  for (; j < _PB_N; j++)
	    {
	      DATA_TYPE sum = path_ik + path_k[j];
	      path_i[j] = path_i[j] < sum ? path_i[j] : sum;
	    }
	}
    }
#else
#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	for (j = 0; j < _PB_N; j++)
	  path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	    path[i][j] : path[i][k] + path[k][j];
    }
#pragma endscop
#endif
}

