static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#if defined(__riscv_vector) && (defined(DATA_TYPE_IS_FLOAT) || defined(DATA_TYPE_IS_DOUBLE))
  for (i = 0; i < _PB_NI; i++) {
    /* Vectorized C[i][j] *= beta */
    j = 0;
#if defined(DATA_TYPE_IS_DOUBLE)
    /* Double precision */
    for (j = 0; j < _PB_NJ; ) {
      size_t vl = __riscv_vsetvl_e64m8(_PB_NJ - j);
      vfloat64m8_t vbeta = __riscv_vfmv_v_f_f64m8(beta, vl);
      vfloat64m8_t vc = __riscv_vle64_v_f64m8(&C[i][j], vl);
      vc = __riscv_vfmul_vv_f64m8(vc, vbeta, vl);
      __riscv_vse64_v_f64m8(&C[i][j], vc, vl);
      j += vl;
    }
#elif defined(DATA_TYPE_IS_FLOAT)
    /* Single precision */
    for (j = 0; j < _PB_NJ; ) {
      size_t vl = __riscv_vsetvl_e32m8(_PB_NJ - j);
      vfloat32m8_t vbeta = __riscv_vfmv_v_f_f32m8(beta, vl);
      vfloat32m8_t vc = __riscv_vle32_v_f32m8(&C[i][j], vl);
      vc = __riscv_vfmul_vv_f32m8(vc, vbeta, vl);
      __riscv_vse32_v_f32m8(&C[i][j], vc, vl);
      j += vl;
    }
#endif

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_val = alpha * A[i][k];
      j = 0;
#if defined(DATA_TYPE_IS_DOUBLE)
      /* Double precision */
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e64m8(_PB_NJ - j);
        vfloat64m8_t va = __riscv_vfmv_v_f_f64m8(a_val, vl);
        vfloat64m8_t vb = __riscv_vle64_v_f64m8(&B[k][j], vl);
        vfloat64m8_t vc = __riscv_vle64_v_f64m8(&C[i][j], vl);
        vfloat64m8_t vprod = __riscv_vfmul_vv_f64m8(va, vb, vl);
        vc = __riscv_vfadd_vv_f64m8(vc, vprod, vl);
        __riscv_vse64_v_f64m8(&C[i][j], vc, vl);
        j += vl;
      }
#elif defined(DATA_TYPE_IS_FLOAT)
      /* Single precision */
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m8(_PB_NJ - j);
        vfloat32m8_t va = __riscv_vfmv_v_f_f32m8(a_val, vl);
        vfloat32m8_t vb = __riscv_vle32_v_f32m8(&B[k][j], vl);
        vfloat32m8_t vc = __riscv_vle32_v_f32m8(&C[i][j], vl);
        vfloat32m8_t vprod = __riscv_vfmul_vv_f32m8(va, vb, vl);
        vc = __riscv_vfadd_vv_f32m8(vc, vprod, vl);
        __riscv_vse32_v_f32m8(&C[i][j], vc, vl);
        j += vl;
      }
#endif
    }
  }
#else
#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++)
	C[i][j] *= beta;
    for (k = 0; k < _PB_NK; k++) {
       for (j = 0; j < _PB_NJ; j++)
	  C[i][j] += alpha * A[i][k] * B[k][j];
    }
  }
#pragma endscop
#endif
}

