#include <riscv_vector.h>
#endif

static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

#if defined(__riscv_vector)
  size_t vlmax = __riscv_vsetvlmax_e64m2();

  // Loop 1: A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE u1_val = u1[i];
    DATA_TYPE u2_val = u2[i];
    for (j = 0; j < _PB_N; j += vlmax) {
      size_t vl = __riscv_vsetvl_e64m2(_PB_N - j);
      vfloat64m2_t vA = __riscv_vle64_v_f64m2(&A[i][j], vl);
      vfloat64m2_t vv1 = __riscv_vle64_v_f64m2(&v1[j], vl);
      vfloat64m2_t vv2 = __riscv_vle64_v_f64m2(&v2[j], vl);
      vfloat64m2_t vtmp1 = __riscv_vfmul_vf_f64m2(vv1, u1_val, vl);
      vfloat64m2_t vtmp2 = __riscv_vfmul_vf_f64m2(vv2, u2_val, vl);
      vA = __riscv_vfadd_vv_f64m2(vA, vtmp1, vl);
      vA = __riscv_vfadd_vv_f64m2(vA, vtmp2, vl);
      __riscv_vse64_v_f64m2(&A[i][j], vA, vl);
    }
  }

  // Loop 2: x[i] = x[i] + beta * A[j][i] * y[j]
  // Use strip-mining with vector reduction
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = x[i];
    for (j = 0; j < _PB_N; j += vlmax) {
      size_t vl = __riscv_vsetvl_e64m2(_PB_N - j);
      vfloat64m2_t vA = __riscv_vle64_v_f64m2(&A[j][i], vl);
      vfloat64m2_t vy = __riscv_vle64_v_f64m2(&y[j], vl);
      vfloat64m2_t vprod = __riscv_vfmul_vv_f64m2(vA, vy, vl);
      sum += beta * __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m2_f64m1(vprod, __riscv_vfmv_v_f_f64m1(0.0, vl), vl));
    }
    x[i] = sum;
  }

  // Loop 3: x[i] = x[i] + z[i]
  for (i = 0; i < _PB_N; i += vlmax) {
    size_t vl = __riscv_vsetvl_e64m2(_PB_N - i);
    vfloat64m2_t vx = __riscv_vle64_v_f64m2(&x[i], vl);
    vfloat64m2_t vz = __riscv_vle64_v_f64m2(&z[i], vl);
    vx = __riscv_vfadd_vv_f64m2(vx, vz, vl);
    __riscv_vse64_v_f64m2(&x[i], vx, vl);
  }

  // Loop 4: w[i] = w[i] + alpha * A[i][j] * x[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = w[i];
    for (j = 0; j < _PB_N; j += vlmax) {
      size_t vl = __riscv_vsetvl_e64m2(_PB_N - j);
      vfloat64m2_t vA = __riscv_vle64_v_f64m2(&A[i][j], vl);
      vfloat64m2_t vx = __riscv_vle64_v_f64m2(&x[j], vl);
      vfloat64m2_t vprod = __riscv_vfmul_vv_f64m2(vA, vx, vl);
      sum += alpha * __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m2_f64m1(vprod, __riscv_vfmv_v_f_f64m1(0.0, vl), vl));
    }
    w[i] = sum;
  }
#else
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x[i] = x[i] + beta * A[j][i] * y[j];

  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      w[i] = w[i] +  alpha * A[i][j] * x[j];
#endif

#pragma endscop
}

