#include <riscv_vector.h>
#endif

static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#if defined(__riscv_vector)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE sum_a = SCALAR_VAL(0.0);
      DATA_TYPE sum_b = SCALAR_VAL(0.0);

      j = 0;
      size_t vlmax = __riscv_vsetvlmax_e64m1();
      vfloat64m1_t vsum_a = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
      vfloat64m1_t vsum_b = __riscv_vfmv_v_f_f64m1(0.0, vlmax);

      for (; j + vlmax <= _PB_N; j += vlmax)
        {
          vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vlmax);

          vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vlmax);
          vfloat64m1_t vtmp_a = __riscv_vfmul_vv_f64m1(va, vx, vlmax);
          vsum_a = __riscv_vfadd_vv_f64m1(vsum_a, vtmp_a, vlmax);

          vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[i][j], vlmax);
          vfloat64m1_t vtmp_b = __riscv_vfmul_vv_f64m1(vb, vx, vlmax);
          vsum_b = __riscv_vfadd_vv_f64m1(vsum_b, vtmp_b, vlmax);
        }

      vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
      vfloat64m1_t vred_a = __riscv_vfredusum_vs_f64m1_f64m1(vsum_a, vzero, vlmax);
      vfloat64m1_t vred_b = __riscv_vfredusum_vs_f64m1_f64m1(vsum_b, vzero, vlmax);
      sum_a = __riscv_vfmv_f_s_f64m1_f64(vred_a);
      sum_b = __riscv_vfmv_f_s_f64m1_f64(vred_b);

      for (; j < _PB_N; j++)
        {
          sum_a += A[i][j] * x[j];
          sum_b += B[i][j] * x[j];
        }

      tmp[i] = sum_a;
      y[i] = alpha * sum_a + beta * sum_b;
    }
#else
#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      y[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	{
	  tmp[i] = A[i][j] * x[j] + tmp[i];
	  y[i] = B[i][j] * x[j] + y[i];
	}
      y[i] = alpha * tmp[i] + beta * y[i];
    }
#pragma endscop
#endif
}

