#include <riscv_vector.h>
#endif

static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
      {
        size_t vlmax = __riscv_vsetvlmax_e64m8();
        vfloat64m8_t v_sum = __riscv_vfmv_v_f_f64m8(0.0, vlmax);
        size_t vl;
        for (i = 0; i < _PB_M; i += vl) {
          vl = __riscv_vsetvl_e64m8(_PB_M - i);
          vfloat64m8_t va = __riscv_vle64_v_f64m8(&A[i][k], vl);
          v_sum = __riscv_vfmacc_vv_f64m8(v_sum, va, va, vl);
        }
        vfloat64m1_t v_red = __riscv_vfredusum_vs_f64m8_f64m1(v_sum, __riscv_vfmv_s_f_f64m1(0.0, __riscv_vsetvlmax_e64m1()), __riscv_vsetvlmax_e64m8());
        nrm = __riscv_vfmv_f_s_f64m1_f64(v_red);
      }
#else
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
#endif

      R[k][k] = SQRT_FUN(nrm);

#if defined(__riscv_vector)
      {
        size_t vl;
        DATA_TYPE rkk = R[k][k];
        for (i = 0; i < _PB_M; i += vl) {
          vl = __riscv_vsetvl_e64m8(_PB_M - i);
          vfloat64m8_t va = __riscv_vle64_v_f64m8(&A[i][k], vl);
          vfloat64m8_t vq = __riscv_vfdiv_vf_f64m8(va, rkk, vl);
          __riscv_vse64_v_f64m8(&Q[i][k], vq, vl);
        }
      }
#else
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];
#endif

      for (j = k + 1; j < _PB_N; j++)
	{
	  R[k][j] = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
          {
            size_t vlmax = __riscv_vsetvlmax_e64m8();
            vfloat64m8_t v_sum = __riscv_vfmv_v_f_f64m8(0.0, vlmax);
            size_t vl;
            for (i = 0; i < _PB_M; i += vl) {
              vl = __riscv_vsetvl_e64m8(_PB_M - i);
              vfloat64m8_t vq = __riscv_vle64_v_f64m8(&Q[i][k], vl);
              vfloat64m8_t va = __riscv_vle64_v_f64m8(&A[i][j], vl);
              v_sum = __riscv_vfmacc_vv_f64m8(v_sum, vq, va, vl);
            }
            vfloat64m1_t v_red = __riscv_vfredusum_vs_f64m8_f64m1(v_sum, __riscv_vfmv_s_f_f64m1(0.0, __riscv_vsetvlmax_e64m1()), __riscv_vsetvlmax_e64m8());
            R[k][j] = __riscv_vfmv_f_s_f64m1_f64(v_red);
          }
#else
	  for (i = 0; i < _PB_M; i++)
	    R[k][j] += Q[i][k] * A[i][j];
#endif

#if defined(__riscv_vector)
          {
            size_t vl;
            DATA_TYPE rkj = R[k][j];
            for (i = 0; i < _PB_M; i += vl) {
              vl = __riscv_vsetvl_e64m8(_PB_M - i);
              vfloat64m8_t va = __riscv_vle64_v_f64m8(&A[i][j], vl);
              vfloat64m8_t vq = __riscv_vle64_v_f64m8(&Q[i][k], vl);
              vfloat64m8_t vprod = __riscv_vfmul_vf_f64m8(vq, rkj, vl);
              va = __riscv_vfsub_vv_f64m8(va, vprod, vl);
              __riscv_vse64_v_f64m8(&A[i][j], va, vl);
            }
          }
#else
	  for (i = 0; i < _PB_M; i++)
	    A[i][j] = A[i][j] - Q[i][k] * R[k][j];
#endif
	}
    }
#pragma endscop

}

