#include <riscv_vector.h>
#endif

static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#if defined(__riscv_vector)
  for (t = 1; t <= TSTEPS; t++) {
    for (i = 1; i < _PB_N-1; i++) {
      for (j = 1; j < _PB_N-1; j++) {
        k = 1;
        size_t vlmax = __riscv_vsetvlmax_e64m4();
        for (; k + (int)vlmax - 1 < _PB_N-1; k += vlmax) {
          size_t vl = __riscv_vsetvl_e64m4(vlmax);

          vfloat64m4_t a_ijk = __riscv_vle64_v_f64m4(&A[i][j][k], vl);
          vfloat64m4_t a_ijk_m1 = __riscv_vle64_v_f64m4(&A[i][j][k-1], vl);
          vfloat64m4_t a_ijk_p1 = __riscv_vle64_v_f64m4(&A[i][j][k+1], vl);
          vfloat64m4_t a_im1jk = __riscv_vle64_v_f64m4(&A[i-1][j][k], vl);
          vfloat64m4_t a_ip1jk = __riscv_vle64_v_f64m4(&A[i+1][j][k], vl);
          vfloat64m4_t a_ijm1k = __riscv_vle64_v_f64m4(&A[i][j-1][k], vl);
          vfloat64m4_t a_ijp1k = __riscv_vle64_v_f64m4(&A[i][j+1][k], vl);

          vfloat64m4_t t2 = __riscv_vfmul_vf_f64m4(a_ijk, 2.0, vl);

          vfloat64m4_t t1 = __riscv_vfadd_vv_f64m4(a_ip1jk, a_im1jk, vl);
          t1 = __riscv_vfsub_vv_f64m4(t1, t2, vl);

          vfloat64m4_t t3 = __riscv_vfadd_vv_f64m4(a_ijp1k, a_ijm1k, vl);
          t3 = __riscv_vfsub_vv_f64m4(t3, t2, vl);

          vfloat64m4_t t4 = __riscv_vfadd_vv_f64m4(a_ijk_p1, a_ijk_m1, vl);
          t4 = __riscv_vfsub_vv_f64m4(t4, t2, vl);

          vfloat64m4_t result = __riscv_vfmadd_vf_f64m4(t1, 0.125, a_ijk, vl);
          result = __riscv_vfmadd_vf_f64m4(t3, 0.125, result, vl);
          result = __riscv_vfmadd_vf_f64m4(t4, 0.125, result, vl);

          __riscv_vse64_v_f64m4(&B[i][j][k], result, vl);
        }
        for (; k < _PB_N-1; k++) {
          B[i][j][k] =   SCALAR_VAL(0.125) * (A[i+1][j][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i-1][j][k])
                       + SCALAR_VAL(0.125) * (A[i][j+1][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j-1][k])
                       + SCALAR_VAL(0.125) * (A[i][j][k+1] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j][k-1])
                       + A[i][j][k];
        }
      }
    }
    for (i = 1; i < _PB_N-1; i++) {
      for (j = 1; j < _PB_N-1; j++) {
        k = 1;
        size_t vlmax = __riscv_vsetvlmax_e64m4();
        for (; k + (int)vlmax - 1 < _PB_N-1; k += vlmax) {
          size_t vl = __riscv_vsetvl_e64m4(vlmax);

          vfloat64m4_t b_ijk = __riscv_vle64_v_f64m4(&B[i][j][k], vl);
          vfloat64m4_t b_ijk_m1 = __riscv_vle64_v_f64m4(&B[i][j][k-1], vl);
          vfloat64m4_t b_ijk_p1 = __riscv_vle64_v_f64m4(&B[i][j][k+1], vl);
          vfloat64m4_t b_im1jk = __riscv_vle64_v_f64m4(&B[i-1][j][k], vl);
          vfloat64m4_t b_ip1jk = __riscv_vle64_v_f64m4(&B[i+1][j][k], vl);
          vfloat64m4_t b_ijm1k = __riscv_vle64_v_f64m4(&B[i][j-1][k], vl);
          vfloat64m4_t b_ijp1k = __riscv_vle64_v_f64m4(&B[i][j+1][k], vl);

          vfloat64m4_t t2 = __riscv_vfmul_vf_f64m4(b_ijk, 2.0, vl);

          vfloat64m4_t t1 = __riscv_vfadd_vv_f64m4(b_ip1jk, b_im1jk, vl);
          t1 = __riscv_vfsub_vv_f64m4(t1, t2, vl);

          vfloat64m4_t t3 = __riscv_vfadd_vv_f64m4(b_ijp1k, b_ijm1k, vl);
          t3 = __riscv_vfsub_vv_f64m4(t3, t2, vl);

          vfloat64m4_t t4 = __riscv_vfadd_vv_f64m4(b_ijk_p1, b_ijk_m1, vl);
          t4 = __riscv_vfsub_vv_f64m4(t4, t2, vl);

          vfloat64m4_t result = __riscv_vfmadd_vf_f64m4(t1, 0.125, b_ijk, vl);
          result = __riscv_vfmadd_vf_f64m4(t3, 0.125, result, vl);
          result = __riscv_vfmadd_vf_f64m4(t4, 0.125, result, vl);

          __riscv_vse64_v_f64m4(&A[i][j][k], result, vl);
        }
        for (; k < _PB_N-1; k++) {
          A[i][j][k] =   SCALAR_VAL(0.125) * (B[i+1][j][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i-1][j][k])
                       + SCALAR_VAL(0.125) * (B[i][j+1][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j-1][k])
                       + SCALAR_VAL(0.125) * (B[i][j][k+1] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j][k-1])
                       + B[i][j][k];
        }
      }
    }
  }
#else
#pragma scop
    for (t = 1; t <= TSTEPS; t++) {
        for (i = 1; i < _PB_N-1; i++) {
            for (j = 1; j < _PB_N-1; j++) {
                for (k = 1; k < _PB_N-1; k++) {
                    B[i][j][k] =   SCALAR_VAL(0.125) * (A[i+1][j][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i-1][j][k])
                                 + SCALAR_VAL(0.125) * (A[i][j+1][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j-1][k])
                                 + SCALAR_VAL(0.125) * (A[i][j][k+1] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j][k-1])
                                 + A[i][j][k];
                }
            }
        }
        for (i = 1; i < _PB_N-1; i++) {
           for (j = 1; j < _PB_N-1; j++) {
               for (k = 1; k < _PB_N-1; k++) {
                   A[i][j][k] =   SCALAR_VAL(0.125) * (B[i+1][j][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i-1][j][k])
                                + SCALAR_VAL(0.125) * (B[i][j+1][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j-1][k])
                                + SCALAR_VAL(0.125) * (B[i][j][k+1] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j][k-1])
                                + B[i][j][k];
               }
           }
       }
    }
#pragma endscop
#endif
}

