static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
#if defined(__riscv_vector)
      {
        size_t n_minus_2 = _PB_N - 2;
        i = 1;

        while (n_minus_2 > 0)
          {
            size_t vl = __riscv_vsetvl_e64m2(n_minus_2);

            vfloat64m2_t va_prev = __riscv_vle64_v_f64m2(&A[i - 1], vl);
            vfloat64m2_t va_curr = __riscv_vle64_v_f64m2(&A[i], vl);
            vfloat64m2_t va_next = __riscv_vle64_v_f64m2(&A[i + 1], vl);

            vfloat64m2_t vsum = __riscv_vfadd_vv_f64m2(va_prev, va_curr, vl);
            vsum = __riscv_vfadd_vv_f64m2(vsum, va_next, vl);

            vfloat64m2_t vresult = __riscv_vfmul_vf_f64m2(vsum, 0.33333, vl);

            __riscv_vse64_v_f64m2(&B[i], vresult, vl);

            i += vl;
            n_minus_2 -= vl;
          }
      }

      {
        size_t n_minus_2 = _PB_N - 2;
        i = 1;

        while (n_minus_2 > 0)
          {
            size_t vl = __riscv_vsetvl_e64m2(n_minus_2);

            vfloat64m2_t vb_prev = __riscv_vle64_v_f64m2(&B[i - 1], vl);
            vfloat64m2_t vb_curr = __riscv_vle64_v_f64m2(&B[i], vl);
            vfloat64m2_t vb_next = __riscv_vle64_v_f64m2(&B[i + 1], vl);

            vfloat64m2_t vsum = __riscv_vfadd_vv_f64m2(vb_prev, vb_curr, vl);
            vsum = __riscv_vfadd_vv_f64m2(vsum, vb_next, vl);

            vfloat64m2_t vresult = __riscv_vfmul_vf_f64m2(vsum, 0.33333, vl);

            __riscv_vse64_v_f64m2(&A[i], vresult, vl);

            i += vl;
            n_minus_2 -= vl;
          }
      }
#else
      for (i = 1; i < _PB_N - 1; i++)
	B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
      for (i = 1; i < _PB_N - 1; i++)
	A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
#endif
    }
#pragma endscop

}

static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
#if defined(__riscv_vector)
      for (i = 1; i < _PB_N - 1; i++)
	{
	  DATA_TYPE *a_row = A[i];
	  DATA_TYPE *a_prev = A[i-1];
	  DATA_TYPE *a_next = A[i+1];
	  DATA_TYPE *b_row = B[i];

	  j = 1;
	  size_t vlmax = __riscv_vsetvlmax_e64m1();
	  for (; j + vlmax <= _PB_N - 1; j += vlmax)
	    {
	      vfloat64m1_t a_center = __riscv_vle64_v_f64m1(&a_row[j], vlmax);
	      vfloat64m1_t a_left = __riscv_vle64_v_f64m1(&a_row[j-1], vlmax);
	      vfloat64m1_t a_right = __riscv_vle64_v_f64m1(&a_row[j+1], vlmax);
	      vfloat64m1_t a_down = __riscv_vle64_v_f64m1(&a_next[j], vlmax);
	      vfloat64m1_t a_up = __riscv_vle64_v_f64m1(&a_prev[j], vlmax);

	      vfloat64m1_t sum = __riscv_vfadd_vv_f64m1(a_center, a_left, vlmax);
	      sum = __riscv_vfadd_vv_f64m1(sum, a_right, vlmax);
	      sum = __riscv_vfadd_vv_f64m1(sum, a_down, vlmax);
	      sum = __riscv_vfadd_vv_f64m1(sum, a_up, vlmax);

	      vfloat64m1_t result = __riscv_vfmul_vf_f64m1(sum, SCALAR_VAL(0.2), vlmax);
	      __riscv_vse64_v_f64m1(&b_row[j], result, vlmax);
	    }
	  for (; j < _PB_N - 1; j++)
	    b_row[j] = SCALAR_VAL(0.2) * (a_row[j] + a_row[j-1] + a_row[j+1] + a_next[j] + a_prev[j]);
	}

      for (i = 1; i < _PB_N - 1; i++)
	{
	  DATA_TYPE *b_row = B[i];
	  DATA_TYPE *b_prev = B[i-1];
	  DATA_TYPE *b_next = B[i+1];
	  DATA_TYPE *a_row = A[i];

	  j = 1;
	  size_t vlmax = __riscv_vsetvlmax_e64m1();
	  for (; j + vlmax <= _PB_N - 1; j += vlmax)
	    {
	      vfloat64m1_t b_center = __riscv_vle64_v_f64m1(&b_row[j], vlmax);
	      vfloat64m1_t b_left = __riscv_vle64_v_f64m1(&b_row[j-1], vlmax);
	      vfloat64m1_t b_right = __riscv_vle64_v_f64m1(&b_row[j+1], vlmax);
	      vfloat64m1_t b_down = __riscv_vle64_v_f64m1(&b_next[j], vlmax);
	      vfloat64m1_t b_up = __riscv_vle64_v_f64m1(&b_prev[j], vlmax);

	      vfloat64m1_t sum = __riscv_vfadd_vv_f64m1(b_center, b_left, vlmax);
	      sum = __riscv_vfadd_vv_f64m1(sum, b_right, vlmax);
	      sum = __riscv_vfadd_vv_f64m1(sum, b_down, vlmax);
	      sum = __riscv_vfadd_vv_f64m1(sum, b_up, vlmax);

	      vfloat64m1_t result = __riscv_vfmul_vf_f64m1(sum, SCALAR_VAL(0.2), vlmax);
	      __riscv_vse64_v_f64m1(&a_row[j], result, vlmax);
	    }
	  for (; j < _PB_N - 1; j++)
	    a_row[j] = SCALAR_VAL(0.2) * (b_row[j] + b_row[j-1] + b_row[j+1] + b_next[j] + b_prev[j]);
	}
#else
      for (i = 1; i < _PB_N - 1; i++)
	for (j = 1; j < _PB_N - 1; j++)
	  B[i][j] = SCALAR_VAL(0.2) * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
      for (i = 1; i < _PB_N - 1; i++)
	for (j = 1; j < _PB_N - 1; j++)
	  A[i][j] = SCALAR_VAL(0.2) * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
#endif
    }
#pragma endscop

}

