static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < i; j++) {
#if defined(__riscv_vector)
      // Vectorized inner loop for A[i][j] -= A[i][k] * A[k][j]
      DATA_TYPE sum = 0.0;
      size_t vl_max = __riscv_vsetvlmax_e64m1();
      vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, vl_max);

      for (k = 0; k + (int)vl_max <= j; k += vl_max) {
        size_t vl = __riscv_vsetvl_e64m1(vl_max);
        vfloat64m1_t v_a_ik = __riscv_vle64_v_f64m1(&A[i][k], vl);
        double temp[32];
        int t;
        for (t = 0; t < (int)vl; t++) {
          temp[t] = A[k+t][j];
        }
        vfloat64m1_t v_a_kj = __riscv_vle64_v_f64m1(temp, vl);
        v_sum = __riscv_vfmacc_vv_f64m1(v_sum, v_a_ik, v_a_kj, vl);
      }
      double sum_arr[32];
      __riscv_vse64_v_f64m1(sum_arr, v_sum, vl_max);
      int t;
      for (t = 0; t < (int)vl_max; t++) {
        sum += sum_arr[t];
      }
      for (; k < j; k++) {
        sum += A[i][k] * A[k][j];
      }
      A[i][j] -= sum;
#else
      for (k = 0; k < j; k++) {
        A[i][j] -= A[i][k] * A[k][j];
      }
#endif
      A[i][j] /= A[j][j];
    }

    for (j = i; j < _PB_N; j++) {
#if defined(__riscv_vector)
      DATA_TYPE sum = 0.0;
      size_t vl_max = __riscv_vsetvlmax_e64m1();
      vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, vl_max);

      for (k = 0; k + (int)vl_max <= i; k += vl_max) {
        size_t vl = __riscv_vsetvl_e64m1(vl_max);
        vfloat64m1_t v_a_ik = __riscv_vle64_v_f64m1(&A[i][k], vl);
        double temp[32];
        int t;
        for (t = 0; t < (int)vl; t++) {
          temp[t] = A[k+t][j];
        }
        vfloat64m1_t v_a_kj = __riscv_vle64_v_f64m1(temp, vl);
        v_sum = __riscv_vfmacc_vv_f64m1(v_sum, v_a_ik, v_a_kj, vl);
      }
      double sum_arr[32];
      __riscv_vse64_v_f64m1(sum_arr, v_sum, vl_max);
      int t;
      for (t = 0; t < (int)vl_max; t++) {
        sum += sum_arr[t];
      }
      for (; k < i; k++) {
        sum += A[i][k] * A[k][j];
      }
      A[i][j] -= sum;
#else
      for (k = 0; k < i; k++) {
        A[i][j] -= A[i][k] * A[k][j];
      }
#endif
    }
  }
#pragma endscop
}

