static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_N; i++) {
    double sum = x1[i];
    j = 0;
    size_t vlmax = __riscv_vsetvlmax_e64m8();
    vfloat64m8_t vsum = __riscv_vfmv_v_f_f64m8(0.0, vlmax);
    for (; j + vlmax <= _PB_N; j += vlmax) {
      vfloat64m8_t va = __riscv_vle64_v_f64m8(&A[i][j], vlmax);
      vfloat64m8_t vy = __riscv_vle64_v_f64m8(&y_1[j], vlmax);
      vsum = __riscv_vfmacc_vv_f64m8(vsum, va, vy, vlmax);
    }
    vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
    sum += __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m8_f64m1(vsum, vzero, vlmax));
    for (; j < _PB_N; j++) {
      sum += A[i][j] * y_1[j];
    }
    x1[i] = sum;
  }
  for (i = 0; i < _PB_N; i++) {
    double sum = x2[i];
    j = 0;
    size_t vlmax = __riscv_vsetvlmax_e64m8();
    vfloat64m8_t vsum = __riscv_vfmv_v_f_f64m8(0.0, vlmax);
    for (; j + vlmax <= _PB_N; j += vlmax) {
      vfloat64m8_t va = __riscv_vle64_v_f64m8(&A[j][i], vlmax);
      vfloat64m8_t vy = __riscv_vle64_v_f64m8(&y_2[j], vlmax);
      vsum = __riscv_vfmacc_vv_f64m8(vsum, va, vy, vlmax);
    }
    vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
    sum += __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m8_f64m1(vsum, vzero, vlmax));
    for (; j < _PB_N; j++) {
      sum += A[j][i] * y_2[j];
    }
    x2[i] = sum;
  }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_N; i++) {
    float sum = x1[i];
    j = 0;
    size_t vlmax = __riscv_vsetvlmax_e32m8();
    vfloat32m8_t vsum = __riscv_vfmv_v_f_f32m8(0.0f, vlmax);
    for (; j + vlmax <= _PB_N; j += vlmax) {
      vfloat32m8_t va = __riscv_vle32_v_f32m8(&A[i][j], vlmax);
      vfloat32m8_t vy = __riscv_vle32_v_f32m8(&y_1[j], vlmax);
      vsum = __riscv_vfmacc_vv_f32m8(vsum, va, vy, vlmax);
    }
    vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvlmax_e32m1());
    sum += __riscv_vfmv_f_s_f32m1_f32(__riscv_vfredusum_vs_f32m8_f32m1(vsum, vzero, vlmax));
    for (; j < _PB_N; j++) {
      sum += A[i][j] * y_1[j];
    }
    x1[i] = sum;
  }
  for (i = 0; i < _PB_N; i++) {
    float sum = x2[i];
    j = 0;
    size_t vlmax = __riscv_vsetvlmax_e32m8();
    vfloat32m8_t vsum = __riscv_vfmv_v_f_f32m8(0.0f, vlmax);
    for (; j + vlmax <= _PB_N; j += vlmax) {
      vfloat32m8_t va = __riscv_vle32_v_f32m8(&A[j][i], vlmax);
      vfloat32m8_t vy = __riscv_vle32_v_f32m8(&y_2[j], vlmax);
      vsum = __riscv_vfmacc_vv_f32m8(vsum, va, vy, vlmax);
    }
    vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvlmax_e32m1());
    sum += __riscv_vfmv_f_s_f32m1_f32(__riscv_vfredusum_vs_f32m8_f32m1(vsum, vzero, vlmax));
    for (; j < _PB_N; j++) {
      sum += A[j][i] * y_2[j];
    }
    x2[i] = sum;
  }
#else
#pragma scop
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x1[i] = x1[i] + A[i][j] * y_1[j];
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x2[i] = x2[i] + A[j][i] * y_2[j];
#pragma endscop
#endif
}

