static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= _PB_N - 2; i++) {
      DATA_TYPE *a_prev = &A[i-1][0];
      DATA_TYPE *a_curr = &A[i][0];
      DATA_TYPE *a_next = &A[i+1][0];

      j = 1;
#if defined(__riscv_vector)
      // Process with RVV vectors using LMUL=8 for maximum throughput
      for (; j + 31 <= _PB_N - 2; ) {
        size_t vl = __riscv_vsetvl_e64m8(32);

        // Load all 9 stencil positions
        vfloat64m8_t v00 = __riscv_vle64_v_f64m8(a_prev + j - 1, vl);
        vfloat64m8_t v01 = __riscv_vle64_v_f64m8(a_prev + j, vl);
        vfloat64m8_t v02 = __riscv_vle64_v_f64m8(a_prev + j + 1, vl);
        vfloat64m8_t v10 = __riscv_vle64_v_f64m8(a_curr + j - 1, vl);
        vfloat64m8_t v11 = __riscv_vle64_v_f64m8(a_curr + j, vl);
        vfloat64m8_t v12 = __riscv_vle64_v_f64m8(a_curr + j + 1, vl);
        vfloat64m8_t v20 = __riscv_vle64_v_f64m8(a_next + j - 1, vl);
        vfloat64m8_t v21 = __riscv_vle64_v_f64m8(a_next + j, vl);
        vfloat64m8_t v22 = __riscv_vle64_v_f64m8(a_next + j + 1, vl);

        // Tree reduction sum for better ILP
        vfloat64m8_t s0 = __riscv_vfadd_vv_f64m8(v00, v01, vl);
        vfloat64m8_t s1 = __riscv_vfadd_vv_f64m8(v02, v10, vl);
        vfloat64m8_t s2 = __riscv_vfadd_vv_f64m8(v11, v12, vl);
        vfloat64m8_t s3 = __riscv_vfadd_vv_f64m8(v20, v21, vl);

        vfloat64m8_t s4 = __riscv_vfadd_vv_f64m8(s0, s1, vl);
        vfloat64m8_t s5 = __riscv_vfadd_vv_f64m8(s2, s3, vl);
        vfloat64m8_t s6 = __riscv_vfadd_vv_f64m8(s4, s5, vl);
        vfloat64m8_t vsum = __riscv_vfadd_vv_f64m8(s6, v22, vl);

        // Multiply by reciprocal of 9.0 instead of divide for speed
        vfloat64m8_t vresult = __riscv_vfmul_vf_f64m8(vsum, (DATA_TYPE)0.1111111111111111, vl);

        __riscv_vse64_v_f64m8(a_curr + j, vresult, vl);

        j += vl;
      }

      // Handle remaining with LMUL=4
      for (; j + 15 <= _PB_N - 2; ) {
        size_t vl = __riscv_vsetvl_e64m4(16);

        vfloat64m4_t v00 = __riscv_vle64_v_f64m4(a_prev + j - 1, vl);
        vfloat64m4_t v01 = __riscv_vle64_v_f64m4(a_prev + j, vl);
        vfloat64m4_t v02 = __riscv_vle64_v_f64m4(a_prev + j + 1, vl);
        vfloat64m4_t v10 = __riscv_vle64_v_f64m4(a_curr + j - 1, vl);
        vfloat64m4_t v11 = __riscv_vle64_v_f64m4(a_curr + j, vl);
        vfloat64m4_t v12 = __riscv_vle64_v_f64m4(a_curr + j + 1, vl);
        vfloat64m4_t v20 = __riscv_vle64_v_f64m4(a_next + j - 1, vl);
        vfloat64m4_t v21 = __riscv_vle64_v_f64m4(a_next + j, vl);
        vfloat64m4_t v22 = __riscv_vle64_v_f64m4(a_next + j + 1, vl);

        vfloat64m4_t s0 = __riscv_vfadd_vv_f64m4(v00, v01, vl);
        vfloat64m4_t s1 = __riscv_vfadd_vv_f64m4(v02, v10, vl);
        vfloat64m4_t s2 = __riscv_vfadd_vv_f64m4(v11, v12, vl);
        vfloat64m4_t s3 = __riscv_vfadd_vv_f64m4(v20, v21, vl);

        vfloat64m4_t s4 = __riscv_vfadd_vv_f64m4(s0, s1, vl);
        vfloat64m4_t s5 = __riscv_vfadd_vv_f64m4(s2, s3, vl);
        vfloat64m4_t s6 = __riscv_vfadd_vv_f64m4(s4, s5, vl);
        vfloat64m4_t vsum = __riscv_vfadd_vv_f64m4(s6, v22, vl);

        vfloat64m4_t vresult = __riscv_vfmul_vf_f64m4(vsum, (DATA_TYPE)0.1111111111111111, vl);

        __riscv_vse64_v_f64m4(a_curr + j, vresult, vl);

        j += vl;
      }

      // Handle remaining with LMUL=2
      for (; j + 7 <= _PB_N - 2; ) {
        size_t vl = __riscv_vsetvl_e64m2(8);

        vfloat64m2_t v00 = __riscv_vle64_v_f64m2(a_prev + j - 1, vl);
        vfloat64m2_t v01 = __riscv_vle64_v_f64m2(a_prev + j, vl);
        vfloat64m2_t v02 = __riscv_vle64_v_f64m2(a_prev + j + 1, vl);
        vfloat64m2_t v10 = __riscv_vle64_v_f64m2(a_curr + j - 1, vl);
        vfloat64m2_t v11 = __riscv_vle64_v_f64m2(a_curr + j, vl);
        vfloat64m2_t v12 = __riscv_vle64_v_f64m2(a_curr + j + 1, vl);
        vfloat64m2_t v20 = __riscv_vle64_v_f64m2(a_next + j - 1, vl);
        vfloat64m2_t v21 = __riscv_vle64_v_f64m2(a_next + j, vl);
        vfloat64m2_t v22 = __riscv_vle64_v_f64m2(a_next + j + 1, vl);

        vfloat64m2_t s0 = __riscv_vfadd_vv_f64m2(v00, v01, vl);
        vfloat64m2_t s1 = __riscv_vfadd_vv_f64m2(v02, v10, vl);
        vfloat64m2_t s2 = __riscv_vfadd_vv_f64m2(v11, v12, vl);
        vfloat64m2_t s3 = __riscv_vfadd_vv_f64m2(v20, v21, vl);

        vfloat64m2_t s4 = __riscv_vfadd_vv_f64m2(s0, s1, vl);
        vfloat64m2_t s5 = __riscv_vfadd_vv_f64m2(s2, s3, vl);
        vfloat64m2_t s6 = __riscv_vfadd_vv_f64m2(s4, s5, vl);
        vfloat64m2_t vsum = __riscv_vfadd_vv_f64m2(s6, v22, vl);

        vfloat64m2_t vresult = __riscv_vfmul_vf_f64m2(vsum, (DATA_TYPE)0.1111111111111111, vl);

        __riscv_vse64_v_f64m2(a_curr + j, vresult, vl);

        j += vl;
      }

      // Handle remaining with LMUL=1
      for (; j + 3 <= _PB_N - 2; ) {
        size_t vl = __riscv_vsetvl_e64m1(4);

        vfloat64m1_t v00 = __riscv_vle64_v_f64m1(a_prev + j - 1, vl);
        vfloat64m1_t v01 = __riscv_vle64_v_f64m1(a_prev + j, vl);
        vfloat64m1_t v02 = __riscv_vle64_v_f64m1(a_prev + j + 1, vl);
        vfloat64m1_t v10 = __riscv_vle64_v_f64m1(a_curr + j - 1, vl);
        vfloat64m1_t v11 = __riscv_vle64_v_f64m1(a_curr + j, vl);
        vfloat64m1_t v12 = __riscv_vle64_v_f64m1(a_curr + j + 1, vl);
        vfloat64m1_t v20 = __riscv_vle64_v_f64m1(a_next + j - 1, vl);
        vfloat64m1_t v21 = __riscv_vle64_v_f64m1(a_next + j, vl);
        vfloat64m1_t v22 = __riscv_vle64_v_f64m1(a_next + j + 1, vl);

        vfloat64m1_t s0 = __riscv_vfadd_vv_f64m1(v00, v01, vl);
        vfloat64m1_t s1 = __riscv_vfadd_vv_f64m1(v02, v10, vl);
        vfloat64m1_t s2 = __riscv_vfadd_vv_f64m1(v11, v12, vl);
        vfloat64m1_t s3 = __riscv_vfadd_vv_f64m1(v20, v21, vl);

        vfloat64m1_t s4 = __riscv_vfadd_vv_f64m1(s0, s1, vl);
        vfloat64m1_t s5 = __riscv_vfadd_vv_f64m1(s2, s3, vl);
        vfloat64m1_t s6 = __riscv_vfadd_vv_f64m1(s4, s5, vl);
        vfloat64m1_t vsum = __riscv_vfadd_vv_f64m1(s6, v22, vl);

        vfloat64m1_t vresult = __riscv_vfmul_vf_f64m1(vsum, (DATA_TYPE)0.1111111111111111, vl);

        __riscv_vse64_v_f64m1(a_curr + j, vresult, vl);

        j += vl;
      }
#endif
      // Scalar cleanup
      for (; j <= _PB_N - 2; j++) {
        a_curr[j] = (a_prev[j-1] + a_prev[j] + a_prev[j+1]
                    + a_curr[j-1] + a_curr[j] + a_curr[j+1]
                    + a_next[j-1] + a_next[j] + a_next[j+1]) / SCALAR_VAL(9.0);
      }
    }
  }
#pragma endscop
}

