#include <riscv_vector.h>
#endif

static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#if defined(__riscv_vector)
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE alpha_Ai_i = alpha * A[i][i];

    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE temp2 = 0;
      DATA_TYPE alpha_Bi_j = alpha * B[i][j];

      for (k = 0; k < i; k++) {
        C[k][j] += alpha_Bi_j * A[i][k];
        temp2 += B[k][j] * A[i][k];
      }
      C[i][j] = beta * C[i][j] + alpha_Bi_j * A[i][i] + alpha * temp2;
    }
  }
#else
#pragma scop
   for (i = 0; i < _PB_M; i++)
      for (j = 0; j < _PB_N; j++ )
      {
        DATA_TYPE temp2 = 0;
        for (k = 0; k < i; k++) {
           C[k][j] += alpha*B[i][j] * A[i][k];
           temp2 += B[k][j] * A[i][k];
        }
        C[i][j] = beta * C[i][j] + alpha*B[i][j] * A[i][i] + alpha * temp2;
     }
#pragma endscop
#endif
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    /* Scale C[i][0..i] by beta using vectors */
    j = 0;
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    {
      int vlmax = __riscv_vsetvlmax_e32m2();
      int vl;
      vfloat32m2_t vbeta = __riscv_vfmv_v_f_f32m2(beta, vlmax);
      for (; j + vlmax <= i + 1; j += vlmax) {
        vl = vlmax;
        vfloat32m2_t vc = __riscv_vle32_v_f32m2((const float*)&C[i][j], vl);
        vc = __riscv_vfmul_vv_f32m2(vc, vbeta, vl);
        __riscv_vse32_v_f32m2((float*)&C[i][j], vc, vl);
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    {
      int vlmax = __riscv_vsetvlmax_e64m2();
      int vl;
      vfloat64m2_t vbeta = __riscv_vfmv_v_f_f64m2(beta, vlmax);
      for (; j + vlmax <= i + 1; j += vlmax) {
        vl = vlmax;
        vfloat64m2_t vc = __riscv_vle64_v_f64m2((const double*)&C[i][j], vl);
        vc = __riscv_vfmul_vv_f64m2(vc, vbeta, vl);
        __riscv_vse64_v_f64m2((double*)&C[i][j], vc, vl);
      }
    }
#endif
    for (; j <= i; j++)
      C[i][j] *= beta;

    /* Main computation: C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k] */
    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE a_val = A[i][k];
      DATA_TYPE b_val = B[i][k];
      DATA_TYPE alpha_b = alpha * b_val;
      DATA_TYPE alpha_a = alpha * a_val;

      j = 0;
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
      {
        int vlmax = __riscv_vsetvlmax_e32m2();
        int vl;
        vfloat32m2_t valpha_b = __riscv_vfmv_v_f_f32m2(alpha_b, vlmax);
        vfloat32m2_t valpha_a = __riscv_vfmv_v_f_f32m2(alpha_a, vlmax);
        for (; j + vlmax <= i + 1; j += vlmax) {
          vl = vlmax;
          vfloat32m2_t vc = __riscv_vle32_v_f32m2((const float*)&C[i][j], vl);
          vfloat32m2_t va = __riscv_vle32_v_f32m2((const float*)&A[j][k], vl);
          vfloat32m2_t vb = __riscv_vle32_v_f32m2((const float*)&B[j][k], vl);
          vc = __riscv_vfmadd_vv_f32m2(va, valpha_b, vc, vl);
          vc = __riscv_vfmadd_vv_f32m2(vb, valpha_a, vc, vl);
          __riscv_vse32_v_f32m2((float*)&C[i][j], vc, vl);
        }
      }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
      {
        int vlmax = __riscv_vsetvlmax_e64m2();
        int vl;
        vfloat64m2_t valpha_b = __riscv_vfmv_v_f_f64m2(alpha_b, vlmax);
        vfloat64m2_t valpha_a = __riscv_vfmv_v_f_f64m2(alpha_a, vlmax);
        for (; j + vlmax <= i + 1; j += vlmax) {
          vl = vlmax;
          vfloat64m2_t vc = __riscv_vle64_v_f64m2((const double*)&C[i][j], vl);
          vfloat64m2_t va = __riscv_vle64_v_f64m2((const double*)&A[j][k], vl);
          vfloat64m2_t vb = __riscv_vle64_v_f64m2((const double*)&B[j][k], vl);
          vc = __riscv_vfmadd_vv_f64m2(va, valpha_b, vc, vl);
          vc = __riscv_vfmadd_vv_f64m2(vb, valpha_a, vc, vl);
          __riscv_vse64_v_f64m2((double*)&C[i][j], vc, vl);
        }
      }
#endif
      for (; j <= i; j++) {
        C[i][j] += A[j][k] * alpha_b + B[j][k] * alpha_a;
      }
    }
  }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#if defined(__riscv_vector)
  for (i = 0; i < n; i++) {
    /* Vectorized C[i][j] *= beta for j = 0..i */
    j = 0;
    if (beta != (DATA_TYPE)1.0) {
      for (; j + 7 <= i; j += 8) {
        size_t vl = 8;
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
        vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
        __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
      }
      for (; j <= i; j++) {
        C[i][j] *= beta;
      }
    }

    for (k = 0; k < m; k++) {
      DATA_TYPE a_ik = A[i][k];
      DATA_TYPE alpha_a_ik = alpha * a_ik;

      j = 0;
      /* Vectorized update with unrolled by 8 using vfloat64m1_t */
      for (; j + 7 <= i; j += 8) {
        size_t vl = 8;
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[j][k], vl);
        va = __riscv_vfmul_vf_f64m1(va, alpha_a_ik, vl);
        vc = __riscv_vfadd_vv_f64m1(vc, va, vl);
        __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
      }
      for (; j <= i; j++) {
        C[i][j] += alpha_a_ik * A[j][k];
      }
    }
  }
#else
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++) {
      for (j = 0; j <= i; j++)
        C[i][j] += alpha * A[i][k] * A[j][k];
    }
  }
#endif
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#if defined(__riscv_vector)
  for (i = 0; i < n; i++)
    {
      DATA_TYPE sum = b[i];

      /* Vectorized dot product of L[i][0..i-1] and x[0..i-1] */
      for (j = 0; j < i; )
        {
          size_t vl = __riscv_vsetvl_e64m8(i - j);
          vfloat64m8_t vL = __riscv_vle64_v_f64m8(&L[i][j], vl);
          vfloat64m8_t vx = __riscv_vle64_v_f64m8(&x[j], vl);
          vfloat64m8_t vprod = __riscv_vfmul_vv_f64m8(vL, vx, vl);
          vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m8_f64m1(vprod, __riscv_vfmv_v_f_f64m1(0.0, 1), vl);
          sum -= __riscv_vfmv_f_s_f64m1_f64(vsum);
          j += vl;
        }

      x[i] = sum / L[i][i];
    }
#else
#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];
      for (j = 0; j < i; j++)
        x[i] -= L[i][j] * x[j];
      x[i] = x[i] / L[i][i];
    }
#pragma endscop
#endif
}

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,m))
{
  int i, j, k;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop
  for (i = 0; i < _PB_M; i++) {
     for (j = 0; j < _PB_N; j++) {
        DATA_TYPE sum = B[i][j];
        for (k = i+1; k < _PB_M; k++)
           sum += A[k][i] * B[k][j];
        B[i][j] = alpha * sum;
     }
  }
#pragma endscop

}
